quests[45813] = { id = 45813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Art Thou, My Sweet", description = "What poor fate! Here we are with the jewelry to buy my beloved's freedom, and she has disappeared! We must inquire of the patrons of this fine establishment. Perhaps they know what befell her.", completion = "Well, she has been taken, but we shall never rest. Join me as my Follower, lead my troops, perform missions for me! Together we will find her!", objectives = "Help to maintain Doloria's \"illusion\" and ask around the Inn to see where Doloria disappeared to.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
