quests[45831] = { id = 45831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunter" }
quests[45833] = { id = 45833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pirate's Bay", description = "While we've made some progress on the Broken Shore, I think it is time for the more subtle tactics of the Uncrowned.\n\nWe've received word of a large cave off the main island, where powerful demons meet to plot our downfall. Tess and Tethys have formulated a plan, but they need your help to see it through.They are waiting for you at Dead Man's Bay in Azsuna.", completion = "Straighten up, Shadowblade. We've got work to do.", objectives = "Meet up with Tess Greymane and Tethys at Dead Man's Bay in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45834] = { id = 45834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Souls", description = "Odyn's worthy are held captive by soul fonts scattered around the Eternal Battlefield. They were destined to become Valarjar before their futures were stolen.\n\nNow, you can restore them to their rightful places. Destroy the soul fonts to release them!", completion = "With the Valarjar leading the vanguard, our offensives will be glorious!", objectives = "Free 15 stolen souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45835] = { id = 45835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "False Orders", description = "As soon as you take down Prix, word will spread like wildfire amongst the crew in the area. I had Tethys forge some orders in her handwriting that should send them away and buy us some more time.\n\nPlant the orders in the marked locations. You should see the results rather quickly.", completion = "They ran right past us on their way out.", objectives = "Plant the False Orders in the marked locations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45836] = { id = 45836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorach's Calling", description = "And with that, the first phase of the plan is complete. It's best we return to Jorach and bring him the news.", completion = "Welcome back, Shadowblade. I assume you've retrieved the gunpowder?", objectives = "Return to Lord Jorach Ravenholdt in the Hall of Shadows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45837] = { id = 45837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creeping Fel" }
quests[45838] = { id = 45838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Azsuna", description = "The demons strike at the heart of our existence, posing a threat to all who inhabit our lands.\n\nRemove the threat before it is too late.", completion = "I'm afraid our fight has only brought us so far. We must press our attack before the Legion advances beyond their stronghold within the Temple of a Thousand Lights!", objectives = "Repel the Burning Legion forces throughout Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45839] = { id = 45839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Stormheim", description = "The eternal foe of our world, the Burning Legion, dare to attack the land of Stormheim!\n\nChampion, now is your call to valor! Find the forces of the Legion and eradicate them!", completion = "Just beyond these cliffs, the forces of the Legion are gathering for their assault. For every moment that passes their number grows.\n\nWe must strike soon before we are overwhelmed!", objectives = "Repel the Burning Legion forces throughout Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45840] = { id = 45840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Highmountain", description = "In my years I have seen disturbances and threats come and go, but never before have I seen such brazen disregard for life. \n\nThe demons may scorch our lands and cause suffering amongst our kin, but we must not stand idly by while they threaten what we have fought so hard to create.\n\nRise to the occasion, {name}. The time has come to stand against the Burning Legion!", completion = "My apologies, {name}. I hope Aviash and I did not offend you. One cannot be too careful during times like these.", objectives = "Repel the Burning Legion forces throughout Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45841] = { id = 45841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Triumphant Report", description = "You should return to your Kirin Tor. I have no doubt they will want to hear the good news!", completion = "I am relieved that you have dealt with immediate threat. We barely have enough resources for the Broken Shore as it is!\n\nStill we have something for you...", objectives = "Speak with Archmage Modera in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45842] = { id = 45842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift From the Six", description = "{name}, without you some of the Legion's strongest agents would still be roaming Azeroth, threatening to undermine all that we've accomplished in this war.\n\nSuch a deed merits more than mere recognition.\n\nIf you would accept it, we would like to formally reward your heroism in the face of such darkness with a portion of our power.", progress = "Are you ready?", completion = "We hope the increased power to your weapon will prove useful on the Broken Shore and beyond.", objectives = "Raise your weapon and receive the Council of Six's gift in the Violet Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45843] = { id = 45843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Omens", description = "We won't be able to defeat Kruul alone.\n\nOnce the portal has stabilized I will send word so we can bring the Highlord to justice.\n\nIn the meantime, you should inform the Kirin Tor of Vazuun's death - and Kruul's return.", completion = "Any luck out there?", objectives = "Speak with Archmage Modera in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45844] = { id = 45844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avocation of Antonidas", description = "Archmage Kalec has requested your presence back in the Hall of the Guardian. He's discovered something he wishes to urgently speak with you about.\n\nPlease see him at your earliest convenience.", completion = "Archmage, I've found something you may be interested in. An old journal of the late Archmage Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish.\n\nIt was a sort of flying disc that could attune itself to the rider's magical specialization.\n\nBut I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.", objectives = "Speak with Archmage Kalec in the Hall of the Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45845] = { id = 45845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Within", description = "The first piece he spoke of was that of fire. He imbued it while investigating the entrance to the Molten Core.\n\nHowever, the power surging through it was too great to control, so he asked Khadgar to take it to Karazhan and see if there were any books on the subject of controlling fire.\n\nPerhaps you should speak with Khadgar and find out what became of the disc.", progress = "Was Khadgar able to remember what he did with the piece?", completion = "You've recovered it! And it is as Antonidas wrote, still surging with great fire magic!", objectives = "Speak with Khadgar about the Tri-Disc of Fire. Follow his instructions after you speak with him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45846] = { id = 45846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chilled to the Core", description = "The next piece Antonidas made was imbued with frost magic. He wrote about a ritual to channel frost energy into the disc with his fellow Archmage, Cedric, but their combined strengths forced too much energy into the disc.\n\nIf I recall, Cedric is helping oversee the reconstruction of Dalaran near the crater where Dalaran once resided.\n\nHopefully he knows where to find the disc.", progress = "After the devastation that befell Dalaran's original home, who knows where that disc may be.", completion = "Ogres took it? Those beasts will grab anything they can I suppose.\n\nRegardless, it's excellent you were able to find it.", objectives = "Speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45847] = { id = 45847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Close to Home", description = "The third piece of the disc was infused with Antonidas' own arcane magic. He did this at the height of his power, but like the other two discs, was unable to finish his work on it.\n\nHe wrote that he gave the piece to Archmage Celindra...\n\nIsn't she the portal trainer here in Dalaran? She must know where the piece is!\n\nQuickly, go speak with her.", progress = "Did she have it?", completion = "To think it was right here in Dalaran the whole time.", objectives = "Speak to Archmage Celindra about the Tri-Disc of the Arcane here in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45848] = { id = 45848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fit For a Pirate", objectives = "Squawk! Tethys is lame! Bad pirate! bad pirate!\n\n{name} better pirate, raaaaawk! Go with you now!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45849] = { id = 45849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "3+ Targets Trait Complete" }
quests[45850] = { id = 45850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AoE Chosen" }
