quests[45853] = { id = 45853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Melee DPS Trait Complete" }
quests[45854] = { id = 45854, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ranged DPS Trait Complete" }
quests[45855] = { id = 45855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tank Trait Complete" }
quests[45856] = { id = 45856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Val'sharah", description = "From the very start of these attacks I've felt as though the demons knew our plans, as if they anticipated our every move. If we are to put an end to this we must focus our attacks at the heart of the beast.\n\nYour efforts have shown these battles are not won by bravery alone, but willingness and sacrifice. I ask that you stand on the battlefield once more among allies to bring this madness to an end.", completion = "You have sacrificed for our lands, brave {class}.\n\nYour perseverance has inspired our brothers and sisters to stand against the Burning Legion.", objectives = "Defeat Dread Vizier Gra'tork in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45861] = { id = 45861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift From the Six", description = "{name}, without you some of the Legion's strongest agents would still be roaming Azeroth, threatening to undermine all that we've accomplished in this war.\n\nSuch a deed merits more than mere recognition.\n\nIf you would accept it, we would like to formally reward your heroism in the face of such darkness with a portion of our power.", progress = "Are you ready?", completion = "We hope the increased power to your weapon will prove useful on the Broken Shore and beyond.", objectives = "Raise your weapon and receive the Council of Six's gift in the Violet Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
