quests[45890] = { id = 45890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancestors and Enemies", description = "I want nothing more than to prove myself by joining our offensive on the Broken Shore, but I'm beginning to doubt my worthiness.\n\nYou see, I found my family's sigil among the demonic runes I've been deciphering. Why the Moonfang crest would be known to the Legion is a mystery to me, but I trust you'll be able to find what connection lies between my ancestors and my enemies.\n\nWhat's left of their village can be found in Val'sharah.", completion = "What business do you have here? Have you come to scavenge what the harpies left behind?", objectives = "Head to Delas' ancestral home in Val'sharah and recover relics from her past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
