quests[45914] = { id = 45914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ch 5 Soulstone Shielded Tracking Quest" }
quests[45915] = { id = 45915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Folly of Levia Laurance", description = "Levia Laurance was once a member of the Kirin Tor, long ago, and a good friend. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good.\n\nLevia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous for all of us if her knowledge fell into their hands.\n\nShe was last seen at the Militant Mystic. Ask around there and see if you can pick up her trail.", objectives = "Ask around the city for information on Levia Laurance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45916] = { id = 45916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Acolyte Imperiled", description = "Truthfully, the Council knows little of Agatha, but she is more than just your average succubus. She has many allies within the sayaad, and is known to command armies of imps that swarm and overwhelm her foes.\n\nTo seek her out is folly, but Ritssyn Flamescowl repays his debts.\n\nCome, let us examine what manner of fel powers this little mage of yours was stumbling her way through...", progress = "Keep these imps off me!", completion = "The amount of power this Levia channeled into this portal is impressive, if unnecessary. Unfortunately, if we don't get it stable, it's likely to collapse and take us with it. \n\nSufficed to say, that would end your mission pretty quick.\n\nI have to concentrate to keep this open, so I'll need your help...", objectives = "Help Ritssyn investigate Levia's ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45917] = { id = 45917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Following the Scent", description = "You will have to continue through the portal without me, {class}. I have assisted you in locating your mage's whereabouts, so I consider my debt to Modera paid.\n\nHowever, I will lend you one of my felhounds to help track this mage down. If she is as powerful as Modera says, then it would be in everyone's best interest that Agatha not be allowed to keep her.\n\nBest of luck, {class}, and try to bring Fhambar back in one piece.", completion = "What... what is going on? \n\nWho are you?", objectives = "Follow Fhambar to Levia's location.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45921] = { id = 45921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thal'xur" }
