quests[45970] = { id = 45970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duty's End" }
quests[45971] = { id = 45971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infernal Phenomena", description = "Do you hear that, shaman? The rumble of the earth as it tries to fight against the Legion's will. Their half-witted eredar are attempting to bend the forces of Azeroth to their will.\n\nHow dare the Legion think they can corrupt my domain? They have assembled their infernals from Azeroth's stone - MY stone! Now they try to bring these new infernals to life.\n\nSabotage their foolish rituals. Crush them! Show them Azeroth's true power!", progress = "The earth is my domain, NOT the Legion's!", completion = "I laughed as their infernals crumbled. They return to Azeroth, as they belong.", objectives = "Interrupt 3 Infernal Rituals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45972] = { id = 45972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Accursed Thicket", description = "There is one last task for you and the Doomstone. Thunderaan will explain all.", objectives = "Speak to Thunderaan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45973] = { id = 45973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unchecked Power" }
quests[45974] = { id = 45974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Urgent Warning", description = "<The soldier is wan and wounded, obviously in tremendous pain.>\n\nBeen held prisoner... since the assault on... the Broken Shore...\n\n<He shudders.>\n\nThe demons... th-they are gathering... preparing...\n\nHad to escape... to warn you. They must... be stopped!", completion = "Greetings, Highlord. I've just been informed about the wounded soldier who escaped from the Broken Shore.\n\nWhat he must have endured...", objectives = "Speak to Lord Maxwell Tyrosus", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[45975] = { id = 45975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Tyrosus turns his eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", completion = "Grim tidings indeed.\n\nI suggest we continue sending our champions to scout out the dangers that await.", objectives = "Use the Scouting Map and complete the mission, \"Menace on the Broken Shore\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
