quests[46020] = { id = 46020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Containment", description = "Kanrethad will be safe in my care, but something must be done about these crystals that hold his fel magic.\n\nIf any should break, the energy inside would find its way back to our friend. I shouldn't need to tell you how devastating it would be if that were to happen.\n\nI will gather the crystals and meet you back at Dreadscar Rift.", completion = "The crystals will be safe here, with each of the council members watching over them.\n\nKanrethad is still recovering, but is well enough to speak.", objectives = "Meet Jubeka Shadowbreaker in Dreadscar Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46021] = { id = 46021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thel'draz" }
quests[46022] = { id = 46022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Urgent Warning", description = "<The soldier is wan and wounded, obviously in tremendous pain.>\n\nBeen held prisoner... since the assault on... the Broken Shore...\n\n<She shudders.>\n\nThe demons... th-they are gathering... preparing...\n\nHad to escape... to warn you. They must... be stopped!", completion = "Greetings, Huntmaster. I've just been informed about the wounded soldier who escaped from the Broken Shore.\n\nWhat she must have endured...", objectives = "Speak to Tactician Tinderfell", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46023] = { id = 46023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Tinderfell turns her eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", completion = "Grim tidings indeed.\n\nI suggest we continue sending our champions to scout out the dangers that await.", objectives = "Use the Scouting Map and complete the mission, \"Menace on the Broken Shore\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46024] = { id = 46024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Urgent Warning", description = "<The soldier is wan and wounded, obviously in tremendous pain.>\n\nBeen held prisoner... since the assault on... the Broken Shore...\n\n<She shudders.>\n\nThe demons... th-they are gathering... preparing...\n\nHad to escape... to warn you. They must... be stopped!", completion = "Greetings, Grandmaster. I've just been informed about the wounded soldier who escaped from the Broken Shore.\n\nWhat she must have endured...", objectives = "Speak to Master Hsu", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46025] = { id = 46025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Master Hsu turns his eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", completion = "Grim tidings indeed.\n\nI suggest we continue sending our champions to scout out the dangers that await.", objectives = "Use the Scouting Map and complete the mission, \"Menace on the Broken Shore\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
