quests[46031] = { id = 46031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Broken Shore", description = "All of us know the price we paid the last time we set foot upon the Broken Shore.\n\n<Siouxsie turns her eyes to the ground.>\n\nI recommend dispatching a scouting team to investigate the Legion's strength. We need to know what we're facing in that accursed place.", completion = "Grim tidings indeed.\n\nI suggest we continue sending our champions to scout out the dangers that await.", objectives = "Use the Scouting Map and complete the mission, \"Menace on the Broken Shore\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46032] = { id = 46032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tormented Return" }
quests[46034] = { id = 46034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Aelthalyste", objectives = "All these priests? They report to you? It's astonishing, really.\n\nI have only one Roland, and it seems you have hundreds!\n\nI think we will get along well, {name}. Very well, indeed.\n\nAllow me to stay, and in return, I will offer you my services.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46035] = { id = 46035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "End of the Risen Threat", description = "Commander Shadowsong sends word that he is prepared to face the late Lord Erdris. I have a letter from him for you.\n\nI'm prepared to teleport you to his location, but there's a snag.\n\nIn order to combat the worst of the fel corruption, you will need to use some Nethershards on the way in. Make sure you have some before speaking with me.", completion = "Another crisis averted! Your effectiveness is without compare.", objectives = "Defeat Lord Erdris Thorn. Speak with War Councilor Victoria to be teleported to Jarod Shadowsong's location.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46036] = { id = 46036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadnaught's Battlegear" }
quests[46037] = { id = 46037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ymirjar's Battlegear" }
