quests[46041] = { id = 46041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlegear of Iron Wrath" }
quests[46042] = { id = 46042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlegear of Iron Wrath" }
quests[46043] = { id = 46043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Aethas Sunreaver", objectives = "Archmage, the events of the past have long weighed heavily upon me. While I do not regret my actions, I do regret what happened. If I could go back and change things...\n\nI hope in time the Kirin Tor - indeed, all of Azeroth - will better understand my loyalties. Thanks to you, crisis has been averted. Please accept my enduring gratitude.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46044] = { id = 46044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Thisalee Crow", objectives = "Look, Archdruid, don't get me wrong. I love Aviana. She's my ancient! But she's a little too passive for me to follow around all the time.\n\nYou, on the other hand? You're the real deal! I want to be in the fray, ruining some demon's day!\n\nSo? Will you take me with you?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46045] = { id = 46045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Nerus Moonfang", objectives = "I know I have much to answer for.\n\nAlthough you have freed my family from their curse, nothing can take away the pain my mistakes have caused them. \n\nDelas has done well to devote herself to the Silver Hand. Do not let my past reflect poorly on her.\n\nI'd like to follow her lead, and lend my aid to your order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46046] = { id = 46046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life's a Lich" }
quests[46047] = { id = 46047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kanrethad Ebonlocke", objectives = "Although my recollection of recent events is still a bit hazy, the power you displayed when dispatching Rezara was something I could never forget.\n\nIt seems fitting that the council chose you as its leader in my absence.\n\nRest assured, I have no desire to challenge their decision. I owe you my life.\n\nLet me serve you and the council. There is much we can learn from each other.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46048] = { id = 46048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Nighthuntress Syrenne", objectives = "Tell me, {name}, are all those among your ranks as dedicated as their leader?\n\nI've been reluctant to trust outsiders, but you and I aren't so different, are we? We're both willing to go to great lengths to protect the things we care about. Our goals seem to align in that regard.\n\nI would like to lend my aid to you and your hunters, if you'll allow it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46049] = { id = 46049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift From Your Tadpole", objectives = "<Your tadpole has prepared a gift for you. What could be inside?>", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46050] = { id = 46050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Minerva Ravensorrow", objectives = "Look, I may be dead and my lungs may serve no purpose, but raising Daumyr to undeath was like a breath of fresh air for me. I ask that you continue to take me under your guidance. Bring me to the battlefield again! I will scatter the bones of any demon that so much as looks at me.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46051] = { id = 46051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - March of the Tadpoles Bit 01" }
quests[46052] = { id = 46052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - March of the Tadpoles Bit 02" }
quests[46053] = { id = 46053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - March of the Tadpoles Bit 03" }
quests[46054] = { id = 46054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - March of the Tadpoles Bit 04" }
quests[46055] = { id = 46055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - March of the Tadpoles Bit 05" }
quests[46057] = { id = 46057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Magatha Grimtotem", objectives = "You are a foolish child. You think you have great power, but you know nothing. The Doomstone should be used for the greatness it can accomplish! It will waste away sitting in the Maelstrom.\n\nPerhaps it was a mistake coming here. Nobundo requests that the Grimtotem stay. I stay for my own reasons, not because he asked. If you need me or my warriors to earn our keep, we will oblige.\n\nBut remember your place.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46058] = { id = 46058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lilian Voss", objectives = "You made quick work of those demons, and I hope you do the same to many more. So long as the Legion extends their influence on our world, they will continue to corrupt our people as well.\n\nI would like to continue to work with you to end this madness. My blades are yours, Shadowblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46059] = { id = 46059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Tess Greymane", objectives = "You've proven your expertise to me many times over, Shadowblade. While my colleagues have already pledged their service to you, I took a step back. Though all rogues step in the shadows, it is of vital importance that my status remains truly secret.\n\nHowever, the threat is too great. We are so close to taking the Legion down... and I want to take on a greater role in it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46060] = { id = 46060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvation", description = "The valley is swarming with fel-corrupted creatures who are beyond saving, yet there still may be some that could use our help.\n\nTake this manaroot salve and apply it to any animals you see. If the fel magic hasn't taken hold, the salve might be able to mend their wounds.", completion = "You risked your life freeing those animals from a life worse than death. I commend you, {name}.", objectives = "Use the Manaroot Salve on fel-infected animals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46061] = { id = 46061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adopt a Tadpole", description = "One day every year, usually in mid-spring, the Winterfin tadpoles are given free reign of the village. I'm not sure why this tradition persists, as it usually results in heavy damage to the their buildings and food stores.\n\nI usually try not to interfere too much with the goings-on of the tribe, but today, I take exception. Go out and see if you can keep an eye on one of the tadpoles.", completion = "Glrm. Mrr glrg.", objectives = "Select your favorite Winterfin tadpole and beckon it to follow you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46062] = { id = 46062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tadpole's Request", description = "Glrrrr! Mrr, mrr, glrrgli!\n\n<Your favorite little tadpole is getting reckless. Maybe he might like some clams?>", progress = "Mrglr?", completion = "Glrrrrms!", objectives = "Obtain 10 Winterfin Clams.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46063] = { id = 46063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wailing Dead" }
quests[46064] = { id = 46064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ways of the World", description = "Mrrga!\n\n<Your tadpole cowers and hides, as he observes the shadowy figure of a large orca passing through the Westrift.>\n\nMrrga... Mrrga...", progress = "Mrrga mr?", completion = "Mrrga mr. Gll-mrrr!", objectives = "Slay Mrrga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46065] = { id = 46065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Impossible Foe", description = "{name}! We have just received word from the Council of Six. They have found Agatha!\n\nModera asked that she be able to brief you through this image crystal.  \n\nGood luck!", completion = "News has reached me of Agatha's demise, as well as her plot to infiltrate the Kirin Tor. If it weren't for your swift action, I fear the damage her sayaad could've done would be irreparable. \n\nMy mages are working to hunt down any of Agatha's remaining allies, but the real victory today belongs to you, {name}.\n\nThe Kirin Tor thanks you.", objectives = "Speak with War Councilor Victoria to be teleported to the Imp Mother's Den and defeat Agatha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46066] = { id = 46066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Fel Bat For You" }
quests[46068] = { id = 46068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brute Wrangling" }
quests[46069] = { id = 46069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worthy of the Title", description = "Highlord, Lord Grayson Shadowbreaker wishes to speak with you about an important matter.\n\nPlease seek him out at Light's Hope Chapel in your order hall at your earliest convenience.", completion = "Highlord! I'd like to speak with you about obtaining a special mount...", objectives = "Speak with Lord Grayson Shadowbreaker in your order hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46070] = { id = 46070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations Underway", description = "As you may or may not recall, I once helped young paladins obtain their first armored mount.\n\nIt was a tedious task that involved months of obtaining materials and sending them all over Azeroth.\n\nThankfully, times have changed and we now have most of those materials at hand. That being said, I wish to help you obtain a new mount, something worthy of your title as Highlord.\n\nIn order for us to begin, I only require that you obtain a barding for us. Something strong, thick, and heavy.", progress = "How goes the search for the barding? Find anything suitable yet?", completion = "<Grayson examines the barding.>\n\nThis is... well, a good start, Highlord. But I think it will have to be strengthened a bit.", objectives = "Obtain a Stonehide Leather Barding from a leatherworker. You may also obtain it from the auction house if you're not a leatherworker or don't know a leatherworker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46071] = { id = 46071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hammer of Dalaran", description = "Should we wish to make this barding worthy of the steed who will bear it, we'll need to upgrade it. Right now it's just good for not getting you kicked off your mount.\n\nSpeak with Alard Schmied in Dalaran. He's a fine smith and will know how to modify this barding into something more befitting our needs.", completion = "Greetings, Highlord. What can I help you with?\n\n<You explain what you need to Alard as he looks over the barding.>\n\nI see. I can certainly help you with your upgrading this, but I'll need a few things first.", objectives = "Speak with Alard Schmied in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46072] = { id = 46072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Full Fel" }
quests[46073] = { id = 46073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break Their Garrison" }
quests[46074] = { id = 46074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leather to Legendary", description = "Let's begin, shall we? I mean, I'll be doing all the work, but you get to watch!\n\n<Alard grins a wide smile at you and begins working.>", progress = "How'd it go? Was Alard able to upgrade the barding?", completion = "<Grayson examines the barding.>\n\nThis is perfect. Exactly what I expected from Alard. Now that we have everything together, there is but one task left.", objectives = "Have Alard upgrade the barding and return with it to Lord Grayson Shadowbreaker at your order hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46075] = { id = 46075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic Hunting" }
quests[46076] = { id = 46076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restless Spirits" }
quests[46077] = { id = 46077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felbound Spirits" }
quests[46078] = { id = 46078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holy: The Bradensbrook Investigation", description = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook!\n\nIs it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid.", completion = "A bit late for the warning, eh? Still, I appreciate that we haven't been forgotten.", objectives = "Go to Bradensbrook in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46079] = { id = 46079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid on the Front Lines", description = "When we settled here, that Hold was just a quiet creepy place that we avoided. Then the elves came back from the dead. With your help we thought it was mostly handled. But now it feels like an army is attacking us!\n\nWe could use more healing at our defense lines. More undead arrive and we have less and less protectors each wave. Any aid to our wounded would be welcomed!", progress = "We can't take anymore losses.", completion = "You've saved many lives this day, {class}. Bradensbrook thanks you.", objectives = "Give aid to the wounded on the east, west, and south defense lines of Bradensbrook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46080] = { id = 46080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quieting the Spirits", description = "An overwhelming attack on Bradensbrook is imminent. Together I believe we can blunt the spear before it is cast.\n\nWhile we are dealing with the commanders, we should put down as many unquiet spirits as we can.\n\nWith their leaders down and their numbers culled, that should give us time to find Erdris Thorn.", progress = "I can see you've brought a lot of \"peace\" in your day, {class}.", completion = "We realize these spirits are misguided, but we have to care about the living more than the dead at this point.\n\nThe attacks should ease off for a while.", objectives = "Slay risen elves and spirits near Bradensbrook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46081] = { id = 46081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leather to Legendary", description = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this.\n\nThere is felslate, but that's a probably too tainted for what you're looking to do with this barding.\n\nYou know, I also like to adorn my pieces with something sparkly, like a jewel. I hear saber's eyes are especially sparkly. Why don't you grab one of those for this as well.", objectives = "Obtain 50 Leystone Ore and 1 Saber's Eye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46082] = { id = 46082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowsong's Return", description = "Well our lines are doing a lot better, thanks to you. A good thing too, because we need the rest!\n\nThat being said, we noticed a big group of bigger, meaner risen coming from the farmstead. They would've given us a hard time, but that Shadowsong fellow has returned and killed them all. He's holding off reinforcements coming from the hold.\n\nI'm guessing he could use a hand. We can hold here until you and Shadowsong sort this out.", completion = "I had hoped this town had found peace after what we've all been through. Somehow restless dead have been stirred into a fury. We need to stop it.", objectives = "Find Jarod Shadowsong outside Bradensbrook in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46083] = { id = 46083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Few Things First", description = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this.\n\nThere is felslate, but that's a probably too tainted for what you're looking to do with this barding.\n\nYou know, I also like to adorn my pieces with something sparkly, like a jewel. I've heard that the elves of Suramar have particularly beautiful ones. Perhaps you could acquire one for this project.", progress = "I doubt you'll have a problem getting the leystone, but the sapphire might be a bit harder to acquire.", completion = "You got them! Now to upgrade your barding.\n\nNever say a blacksmith can't improve on a leatherworker's work, I always say. I mean never. I mean... well you know what I mean.", objectives = "Obtain 25 Leystone Ore and a Suramarian Sapphire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46089] = { id = 46089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hiding In Plain Sight", description = "Greetings, Shadowblade.\n\nI hope you are not too upset that I began without you, I have a bit of trouble controlling myself around the mindless undead.\n\nYes, you heard me right. Taerir, the very Taerir that has been standing in the Hall of Shadows for many months now, was the undead pawn of a dreadlord.\n\nAnd there are more of them - in our cities, rising through the ranks of the aristocracy, growing in power and influence, and nearly undetectable.", progress = "Your blade is not yet bloody enough.", completion = "We have shown the demons why they should truly fear the darkness. Now, Lord Ravenholdt has something for you from his personal collection.", objectives = "Assassinate the infiltrating homunculi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[46090] = { id = 46090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Elite 01" }
